WITH base AS (SELECT id, supplier_name, country, city, rating, CASE WHEN country = 'TH' THEN 1 ELSE 0 END AS is_th FROM suppliers WHERE country NOT IN ('TH', 'UK', 'DE')), valid AS (SELECT id, country, city, rating, TRIM(city) AS clean_city, COALESCE(city, 'N/A') AS resolved_city FROM base WHERE city IS NOT NULL AND supplier_name LIKE '%Paci%'), latest AS (SELECT id, city FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY city ORDER BY rating, id) AS row_num FROM valid) t WHERE row_num = 1), not_flagged AS (SELECT s.* FROM latest s WHERE NOT EXISTS (SELECT 1 FROM products ch WHERE ch.supplier_id = s.id AND MONTH(ch.launch_date) IN (7, 8, 10))) SELECT city, COUNT_IF(city = 'New York') AS new_york_events, COUNT(*) AS row_count, COUNT_IF(city = 'Bangkok') AS bangkok_events, SIZE(COLLECT_SET(city)) AS num_cities FROM not_flagged GROUP BY 1 HAVING num_cities < 1000 ORDER BY new_york_events NULLS LAST;
